Lemma dex_elim_1 : forall (A1 : Type) (P : A1 -> Prop) (G : Prop),
  (forall x1, P x1 -> G) -> (exists x1, P x1) -> G.
Proof. intros A1 P G K H. destruct H as [x1 H]. exact (K x1 H). Qed.
