Ltac2 dex_nmax () : int := 40.

Ltac2 dex_fail (s : string) := Control.zero (Tactic_failure (Some (Message.of_string s))).
Ltac2 dex_is_ind (h : constr) (r : constr) : bool :=
  match Constr.Unsafe.kind h with
  | Constr.Unsafe.Ind i _ => (match Constr.Unsafe.kind r with Constr.Unsafe.Ind j _ => Ind.equal i j | _ => false end)
  | _ => false
  end.

Ltac2 dex_var_of (v : Ltac1.t) : ident :=
  match Ltac1.to_ident v with
  | Some i => i
  | None =>
    match Ltac1.to_constr v with
    | Some c => match Constr.Unsafe.kind c with
                | Constr.Unsafe.Var i => i
                | _ => dex_fail "dex: not a hypothesis"
                end
    | None =>
      match Ltac1.to_intro_pattern v with
      | Some (Std.IntroNaming (Std.IntroIdentifier i)) => i
      | _ => dex_fail "dex: not an identifier"
      end
    end
  end.

(* [comment removed for export] *)
Ltac2 rec dex_tele (exr : constr) (t : constr) (fuel : int) (doms : constr list) (bs : binder list) : (constr list) * (binder list) * constr :=
  if Int.le fuel 0 then (List.rev doms, bs, t) else
  match Constr.Unsafe.kind t with
  | Constr.Unsafe.App h args =>
      if Bool.and (dex_is_ind h exr) (Int.equal (Array.length args) 2) then
        let a := Array.get args 0 in
        match Constr.Unsafe.kind (Array.get args 1) with
        | Constr.Unsafe.Lambda b body =>
            (* [comment removed for export] *)
            if Constr.Unsafe.closedn 0 a then dex_tele exr body (Int.sub fuel 1) (a :: doms) (b :: bs)
            else (List.rev doms, bs, t)
        | _ => (List.rev doms, bs, t)
        end
      else (List.rev doms, bs, t)
  | _ => (List.rev doms, bs, t)
  end.

