Ltac2 dex_beta_premise () : unit :=
  let g := Control.goal () in
  match Constr.Unsafe.kind g with
  | Constr.Unsafe.Prod b cod =>
      let ty := Constr.Binder.type b in
      match Constr.Unsafe.kind ty with
      | Constr.Unsafe.App h args =>
          let rec strip (c : constr) (k : int) : constr option :=
            if Int.le k 0 then Some c else
            match Constr.Unsafe.kind c with
            | Constr.Unsafe.Lambda _ b => strip b (Int.sub k 1)
            | _ => None
            end in
          let n := Array.length args in
          (match Constr.Unsafe.kind h with
           | Constr.Unsafe.Lambda _ _ =>
             (match strip h n with
              | Some bd =>
                  let ty' := Constr.Unsafe.substnl (List.rev (Array.to_list args)) 0 bd in
                  let g' := Constr.Unsafe.make (Constr.Unsafe.Prod (Constr.Binder.make (Constr.Binder.name b) ty') cod) in
                  Std.change None (fun _ => g') { Std.on_hyps := Some []; Std.on_concl := Std.AllOccurrences }
              | None => () end)
           | _ => () end)
      | _ => ()
      end
  | _ => ()
  end.

Ltac dex_beta_premise := ltac2:(Control.enter dex_beta_premise).

(* [comment removed for export] *)
Ltac2 dd_nf_concl () : unit :=
  let g := Control.goal () in
  let g' := Std.eval_cbv { Std.rStrength := Std.Norm; Std.rBeta := true; Std.rMatch := true; Std.rFix := true; Std.rCofix := true;
                           Std.rZeta := false; Std.rDelta := false; Std.rConst := [] } g in
  if Constr.equal g g' then () else Std.change None (fun _ => g') { Std.on_hyps := Some []; Std.on_concl := Std.AllOccurrences }.
Ltac dd_nf_concl := ltac2:(Control.enter dd_nf_concl).

Ltac dex_intros_n n PO := do n (let x := fresh "x" in intro x); dex_beta_premise; intro PO.
Ltac dand_intros_n n PO := do n (let H := fresh "PC" in intro H); intro PO.

Ltac2 dex_apply (po : ident) (t' : constr) : unit :=
  let (doms, bs, body) := dex_tele '@ex t' (dex_nmax ()) [] [] in
  let n := List.length doms in
  if Int.lt n 2 then dex_fail "dex: short telescope" else
  let lem := dex_elim_lemma n in
  let p := List.fold_left (fun acc b => Constr.Unsafe.make (Constr.Unsafe.Lambda b acc)) body bs in
  let g := Control.goal () in
  let hd := Constr.Unsafe.make (Constr.Unsafe.App lem (Array.of_list (List.append doms [p; g]))) in
  let pov := Control.hyp po in
  Control.refine (fun () => open_constr:($hd _ $pov));
  Std.clear [po];
  ltac1:(k h |- dex_intros_n k h) (Ltac1.of_int n) (Ltac1.of_ident po).

Ltac dex_apply PO T' := let f := ltac2:(po t |- Control.enter (fun () => dex_apply (dex_var_of po) (Option.get (Ltac1.to_constr t)))) in f PO T'.

Ltac destruct_exs_ref PO :=
  let T := type of PO in let T' := eval hnf in T in
  lazymatch T' with
  | ex _ => let x := fresh "x" in destruct PO as [x PO]; destruct_exs_ref PO
  | _ => idtac
  end.

Ltac destruct_exs_diet_core PO :=
  let T := type of PO in let T' := eval hnf in T in
  lazymatch T' with
  | ex _ =>
      tryif dex_apply PO T'
      then destruct_exs_diet_core PO
      else (let x := fresh "x" in destruct PO as [x PO]; destruct_exs_diet_core PO)
  | _ => idtac
  end.

(* [comment removed for export] *)
Ltac2 rec dand_conjs (andr : constr) (t : constr) (fuel : int) : constr list :=
  if Int.le fuel 1 then [t] else
  match Constr.Unsafe.kind t with
  | Constr.Unsafe.App h args =>
      if Bool.and (dex_is_ind h andr) (Int.equal (Array.length args) 2) then
        Array.get args 0 :: dand_conjs andr (Array.get args 1) (Int.sub fuel 1)
      else [t]
  | _ => [t]
  end.

Ltac2 dand_apply (po : ident) : unit :=
  let t := Constr.type (Control.hyp po) in
  let cs := dand_conjs '@and t (dex_nmax ()) in
  let n := List.length cs in
  if Int.lt n 2 then dex_fail "dand: not a conjunction" else
  let lem := dand_elim_lemma n in
  let g := Control.goal () in
  let hd := Constr.Unsafe.make (Constr.Unsafe.App lem (Array.of_list (List.append cs [g]))) in
  let pov := Control.hyp po in
  Control.refine (fun () => open_constr:($hd _ $pov));
  Std.clear [po];
  ltac1:(k h |- dand_intros_n k h) (Ltac1.of_int (Int.sub n 1)) (Ltac1.of_ident po).
Ltac dand_apply PO := let f := ltac2:(po |- Control.enter (fun () => dand_apply (dex_var_of po))) in f PO.

Ltac destruct_ands_ref PO :=
  lazymatch type of PO with
  | _ /\ _ => let H := fresh "PC" in destruct PO as [H PO]; destruct_ands_ref PO
  | _ => idtac
  end.

Ltac destruct_ands_diet_core PO :=
  lazymatch type of PO with
  | _ /\ _ => first [ dand_apply PO; destruct_ands_diet_core PO | destruct_ands_ref PO ]
  | _ => idtac
  end.

