(* [comment removed for export] *)
Ltac2 dd_binary (p : Std.intro_pattern) : (Std.intro_pattern * Std.intro_pattern) option :=
  match p with
  | Std.IntroAction a =>
      (match a with
       | Std.IntroOrAndPattern oa =>
           (match oa with
            | Std.IntroAndPattern l => (match l with [x; y] => Some (x, y) | _ => None end)
            | Std.IntroOrPattern ll => (match ll with [l] => (match l with [x; y] => Some (x, y) | _ => None end) | _ => None end)
            end)
       | _ => None end)
  | _ => None
  end.
Ltac2 dd_is_naming (p : Std.intro_pattern) : bool :=
  match p with Std.IntroNaming _ => true | _ => false end.

Ltac2 dd_concl_is_prop () : bool := Constr.equal (Constr.type (Control.goal ())) 'Prop.

(* [comment removed for export] *)
Ltac2 rec dd_ex_run (t : constr) (p : Std.intro_pattern) (fuel : int)
   (doms : constr list) (bs : binder list) (ps : Std.intro_pattern list)
   : (constr list) * (binder list) * (Std.intro_pattern list) * constr * Std.intro_pattern :=
  let stop () := (List.rev doms, bs, List.rev ps, t, p) in
  if Int.le fuel 0 then stop () else
  match dd_binary p with
  | None => stop ()
  | Some (px, prest) =>
    if Bool.neg (dd_is_naming px) then stop () else
    match Constr.Unsafe.kind t with
    | Constr.Unsafe.App h args =>
        if Bool.and (dex_is_ind h '@ex) (Int.equal (Array.length args) 2) then
          let a := Array.get args 0 in
          match Constr.Unsafe.kind (Array.get args 1) with
          | Constr.Unsafe.Lambda b body =>
              if Constr.Unsafe.closedn 0 a then dd_ex_run body prest (Int.sub fuel 1) (a :: doms) (b :: bs) (px :: ps)
              else stop ()
          | _ => stop ()
          end
        else stop ()
    | _ => stop ()
    end
  end.

(* [comment removed for export] *)
Ltac2 rec dd_and_run (t : constr) (p : Std.intro_pattern) (fuel : int) (cs : constr list) (ps : Std.intro_pattern list)
   : (constr list) * (Std.intro_pattern list) * constr * Std.intro_pattern :=
  let stop () := (List.rev cs, List.rev ps, t, p) in
  if Int.le fuel 1 then stop () else
  match dd_binary p with
  | None => stop ()
  | Some (px, prest) =>
    match Constr.Unsafe.kind t with
    | Constr.Unsafe.App h args =>
        if Bool.and (dex_is_ind h '@and) (Int.equal (Array.length args) 2) then
          dd_and_run (Array.get args 1) prest (Int.sub fuel 1) (Array.get args 0 :: cs) (px :: ps)
        else stop ()
    | _ => stop ()
    end
  end.

Ltac2 dd_intro1 (p : Std.intro_pattern) : unit := Std.intros false [p].
(* [comment removed for export] *)
Ltac2 rec dd_intro_seq (ps : Std.intro_pattern list) (k : unit -> unit) : unit :=
  match ps with
  | [] => k ()
  | p :: r => dd_intro1 p; Control.enter (fun () => dd_intro_seq r k)
  end.

(* [comment removed for export] *)
Ltac2 rec dd_go (c : constr) (clr : ident option) (p : Std.intro_pattern) (plain : constr -> Std.intro_pattern -> unit) (top : bool) : unit :=
  if Bool.neg (dd_concl_is_prop ()) then dex_fail "ddestruct: goal not in Prop" else
  let t := Std.eval_hnf (Constr.type c) in
  let finish_rest (trest : constr) (prest : Std.intro_pattern) : unit :=
    (* [comment removed for export] *)
    match dd_binary prest with
    | None => dd_intro1 prest
    | Some _ =>
        let h := Fresh.in_goal @dd_tmp in
        Std.intros false [Std.IntroNaming (Std.IntroIdentifier h)];
        dd_go (Control.hyp h) (Some h) prest plain false
    end in
  let (doms, bs, pxs, tbody, prest) := dd_ex_run t p (dex_nmax ()) [] [] [] in
  let n := List.length doms in
  if Int.ge n 1 then
    (let lem := dex_elim_lemma n in
     let pl := List.fold_left (fun acc b => Constr.Unsafe.make (Constr.Unsafe.Lambda b acc)) tbody bs in
     let g := Control.goal () in
     let hd := Constr.Unsafe.make (Constr.Unsafe.App lem (Array.of_list (List.append doms [pl; g]))) in
     Control.refine (fun () => open_constr:($hd _ $c));
     (match clr with Some i => Std.clear [i] | None => () end);
     (* [comment removed for export] *)
     let prem := Constr.Unsafe.make (Constr.Unsafe.Prod (Constr.Binder.make None tbody) g) in
     let g' := List.fold_left (fun acc b => Constr.Unsafe.make (Constr.Unsafe.Prod (Constr.Binder.make (Some @x) (Constr.Binder.type b)) acc)) prem bs in
     Std.change None (fun _ => g') { Std.on_hyps := Some []; Std.on_concl := Std.AllOccurrences };
     dd_intro_seq pxs (fun () => finish_rest tbody prest))
  else
    (let (cs, pcs, tlast, plast) := dd_and_run t p (dex_nmax ()) [] [] in
     let m := List.length cs in
     if Int.ge m 1 then
       (let lem := dand_elim_lemma (Int.add m 1) in
        let g := Control.goal () in
        let hd := Constr.Unsafe.make (Constr.Unsafe.App lem (Array.of_list (List.append cs [tlast; g]))) in
        Control.refine (fun () => open_constr:($hd _ $c));
        (match clr with Some i => Std.clear [i] | None => () end);
        dd_intro_seq pcs (fun () => finish_rest tlast plast))
     else
       (if top then dex_fail "ddestruct: not an ex/and telescope with an and-pattern" else plain c p)).


(* [comment removed for export] *)
Ltac2 dd_next_hyp (h : ident) : ident option :=
  let rec go (l : (ident * constr option * constr) list) : ident option :=
    match l with
    | [] => None
    | (i, _, _) :: r => if Ident.equal i h then (match r with [] => None | (j, _, _) :: _ => Some j end) else go r
    end in
  go (Control.hyps ()).
Ltac2 dd_names () : ident list := List.map (fun (i, _, _) => i) (Control.hyps ()).
Ltac2 dd_restore_position (old : ident list) (next : ident option) : unit :=
  match next with
  | None => ()
  | Some n =>
      if Bool.neg (List.exist (fun i => Ident.equal i n) (dd_names ())) then () else
      let rec after (l : ident list) : ident list :=
        match l with [] => [] | i :: r => if Ident.equal i n then r else after r end in
      let news := List.filter (fun i => Bool.neg (List.exist (fun j => Ident.equal i j) old)) (after (dd_names ())) in
      List.iter (fun i => Control.plus (fun () => Std.move i (Std.MoveAfter n)) (fun _ => ())) news
  end.

Ltac2 dd_entry0 (c : Ltac1.t) (p : Ltac1.t) (clear_var : bool) : unit :=
  let cc := Option.get (Ltac1.to_constr c) in
  let pp := match Ltac1.to_intro_pattern p with Some x => x | None => dex_fail "ddestruct: not an intro pattern" end in
  (* [comment removed for export] *)
  let clr := if clear_var then (match Constr.Unsafe.kind cc with
                                | Constr.Unsafe.Var i => (match Env.get [i] with None => Some i | Some _ => None end)
                                | _ => None end) else None in
  let old := List.filter (fun i => match clr with Some j => Bool.neg (Ident.equal i j) | None => true end) (dd_names ()) in
  let next := match clr with Some i => dd_next_hyp i | None => None end in
  dd_go cc clr pp (fun c' p' => ltac1:(c0 p0 |- destruct c0 as p0) (Ltac1.of_constr c') (Ltac1.of_intro_pattern p')) true;
  Control.enter (fun () => dd_restore_position old next; dd_nf_concl ()).

Ltac2 dd_entry (c : Ltac1.t) (p : Ltac1.t) (clear_var : bool) : unit := Control.enter (fun () => dd_entry0 c p clear_var).

Tactic Notation "ddestruct" constr(c) "as" simple_intropattern(p) :=
  first [ (let f := ltac2:(c0 p0 |- dd_entry c0 p0 true) in f c p) | destruct c as p ].
Tactic Notation "dpose" constr(c) "as" simple_intropattern(p) :=
  first [ (let f := ltac2:(c0 p0 |- dd_entry c0 p0 false) in f c p) | pose proof c as p ].

Ltac2 dd_with_position (h : ident) (tac : unit -> unit) : unit :=
  let old := List.filter (fun i => Bool.neg (Ident.equal i h)) (dd_names ()) in
  let next := dd_next_hyp h in
  tac ();
  Control.enter (fun () => dd_restore_position old next).
Ltac dd_with_position PO tac := let f := ltac2:(po t |- Control.enter (fun () => dd_with_position (dex_var_of po) (fun () => Ltac1.run t))) in f PO tac.
Ltac destruct_exs_diet PO :=
  let T := type of PO in let T' := eval hnf in T in
  lazymatch T' with
  | ex _ => dd_with_position PO ltac:(destruct_exs_diet_core PO); dd_nf_concl
  | _ => idtac
  end.
Ltac destruct_ands_diet PO :=
  lazymatch type of PO with
  | _ /\ _ => dd_with_position PO ltac:(destruct_ands_diet_core PO); dd_nf_concl
  | _ => idtac
  end.

