(* [comment removed for export] *)
Ltac2 rec dxi_wits (f : constr) (doms : constr list) (ws : preterm list option) (acc : constr list) : constr * constr list :=
  match doms with
  | [] => (f, List.rev acc)
  | a :: dr =>
      match ws with
      | Some wl =>
          (match wl with
           | w :: wr =>
               let wc := Constr.Pretype.pretype Constr.Pretype.Flags.constr_flags (Constr.Pretype.expected_oftype a) w in
               dxi_wits (Constr.Unsafe.make (Constr.Unsafe.App f (Array.of_list [wc]))) dr (Some wr) (wc :: acc)
           | [] => Control.throw Not_found end)
      | None =>
          let f' := open_constr:($f _) in
          let ev := match Constr.Unsafe.kind f' with
                    | Constr.Unsafe.App _ args => Array.get args (Int.sub (Array.length args) 1)
                    | _ => Control.throw Not_found end in
          dxi_wits f' dr None (ev :: acc)
      end
  end.

Ltac2 dex_intro_core (limit : int) (ws : preterm list option) : unit :=
  let g := Control.goal () in
  let (doms, bs, body) := dex_tele '@ex g limit [] [] in
  let n := List.length doms in
  if Int.lt n 1 then dex_fail "dex_intro: not an ex-nest" else
  (match ws with Some wl => if Int.equal (List.length wl) n then () else dex_fail "dex_intro: witness count" | None => () end);
  let lem := dex_intro_lemma n in
  let p := List.fold_left (fun acc b => Constr.Unsafe.make (Constr.Unsafe.Lambda b acc)) body bs in
  let hd := Constr.Unsafe.make (Constr.Unsafe.App lem (Array.of_list (List.append doms [p]))) in
  let (f, wits) := dxi_wits hd doms ws [] in
  Control.refine (fun () => open_constr:($f _));
  (* [comment removed for export] *)
  Control.enter (fun () =>
    let b' := Constr.Unsafe.substnl (List.rev wits) 0 body in
    Std.change None (fun _ => b') { Std.on_hyps := Some []; Std.on_concl := Std.AllOccurrences }).

Ltac2 dex_count_syntactic (limit : int) : int :=
  let (doms, _, _) := dex_tele '@ex (Control.goal ()) limit [] [] in List.length doms.

(* [comment removed for export] *)
Ltac2 rec deexists_go (n : int) : unit :=
  if Int.le n 0 then () else
  let k := dex_count_syntactic (if Int.lt n (dex_nmax ()) then n else dex_nmax ()) in
  if Int.ge k 2 then (dex_intro_core k None; Control.enter (fun () => deexists_go (Int.sub n k)))
  else (ltac1:(eexists); Control.enter (fun () => deexists_go (Int.sub n 1))).
Tactic Notation "deexists" integer(n) :=
  first [ (let f := ltac2:(k |- Control.enter (fun () => deexists_go (Option.get (Ltac1.to_int k)))) in f n) | do n eexists ].
Ltac2 rec dex_eexists_all_go () : unit :=
  let k := dex_count_syntactic (dex_nmax ()) in
  if Int.ge k 2 then (dex_intro_core k None; Control.enter dex_eexists_all_go)
  else (match Constr.Unsafe.kind (Control.goal ()) with
        | Constr.Unsafe.App h _ => if dex_is_ind h '@ex then (ltac1:(eexists); Control.enter dex_eexists_all_go) else ()
        | _ => () end).
Ltac dex_eexists_all := ltac2:(Control.enter dex_eexists_all_go).

Ltac2 dexists_go (l : Ltac1.t) : unit :=
  let ws := List.map (fun w => match Ltac1.to_preterm w with Some p => p | None => dex_fail "dexists: witness" end)
                     (match Ltac1.to_list l with Some x => x | None => dex_fail "dexists: list" end) in
  let n := List.length ws in
  if Int.lt n 2 then dex_fail "dexists: single witness" else
  if Int.gt n (dex_nmax ()) then dex_fail "dexists: too many" else
  dex_intro_core n (Some ws).
Ltac2 dexists_fallback (l : Ltac1.t) : unit :=
  List.iter (fun w => Control.enter (fun () => ltac1:(w0 |- exists w0) w))
            (match Ltac1.to_list l with Some x => x | None => dex_fail "dexists: list" end).
Tactic Notation "dexists" ne_uconstr_list_sep(l, ",") :=
  first [ (let f := ltac2:(l0 |- Control.enter (fun () => dexists_go l0)) in f l) | (let f := ltac2:(l0 |- dexists_fallback l0) in f l) ].

